 internal string MorphLabel(Morph m)=>m.Name;
 internal string MorphState(Morph m)=>facePreview.PreviewState(m);
 internal string MorphDetails(Morph m)=>L.T("안정 ID")+": "+m.Id+"\n"+L.T("모프 목록: 사용 가능")+"\n"+L.T("미리보기")+": "+facePreview.PreviewState(m)+"\n"+L.T(m.Backend=="MFEE"&&mfee.Entries.Any(e=>e.ApiRegistered&&e.Name.Equals(m.Name,StringComparison.OrdinalIgnoreCase))?"MFEE 등록: 진단 기록에서 확인됨":"MFEE 등록: 등록 정보 미확인")+"\n"+L.T("게임 적용: 게임에서 확인 필요");
 internal void RetryMorph(Morph m){facePreview.EnsureMorph(m,true);Refresh();}
 internal void ChooseMorphTri()=>facePreview.ChooseTri();
 internal string MorphChannel(Morph m)=>Editing?.Channels.FirstOrDefault(c=>c.Value.Morphs.Contains(m)).Key??group;
 internal void MoveMorph(Morph m,string channel){if(Editing==null||channel==MorphChannel(m))return;foreach(var c in Editing.Channels.Values)c.Morphs.Remove(m);if(!Editing.Channels.ContainsKey(channel))Editing.Channels[channel]=new();Editing.Channels[channel].Morphs.Add(m);Changed();FocusMorph(m);}
 void Open(){var d=new OpenFileDialog{Filter=L.T("표정 프리셋|*.facialpreset.json;*.json")};if(d.ShowDialog()==true){var p=PresetFile.Load(d.FileName);Add(p,d.FileName);}}
 void Save(bool other){if(clipPanel?.Active==true){clipPanel.Save();return;}if(doc==null)return;string? path=other?null:doc.Path;if(path==null){var d=new SaveFileDialog{Filter=L.T("표정 프리셋|*.facialpreset.json"),FileName="preset.facialpreset.json"};if(d.ShowDialog()!=true)return;path=d.FileName;}PresetFile.Save(path,Editing!);doc.Path=path;doc.Dirty=false;presets.Items.Refresh();}

 void Delete(){if(doc==null)return;if(MessageBox.Show(L.T("저장하지 않은 변경은 잃게 됩니다. 목록에서 제거할까요? 취소하려면 아니요를 누르세요. 저장 파일은 삭제하지 않습니다."),L.T("프리셋 제거"),MessageBoxButton.YesNo)!=MessageBoxResult.Yes)return;var old=doc;presets.Items.Remove(old);documents.Remove(old);if(documents.Count>0)presets.SelectedIndex=0;else Add(new Preset());}
}
